-- Catálogo SAIH Júcar (CHJ): estaciones y sensores verificados contra saih.chj.es el 25-08-2026.
-- Las coordenadas del portal son UTM 30N ETRS89 (EPSG:25830) pese a llamarse fldNCoordGPSLat/Lon.

insert into sources (id, name, kind, url) values
  ('saih', 'SAIH Júcar (CHJ)', 'official', 'https://saih.chj.es');

create table sensors (
  id             text primary key,
  source         text not null references sources(id),
  station_id     text not null references stations(id),
  external_id    text not null,
  variable       text not null,
  unit           text not null,
  enabled        boolean not null default true,
  threshold_low  double precision,
  threshold_mid  double precision,
  threshold_high double precision,
  meta           jsonb not null default '{}'::jsonb,
  unique (source, external_id, variable)
);
create index sensors_station_idx on sensors (station_id, variable);

